import {NavigationBasemap} from './navigation-basemap-20261118.js';
export function navigationTransform(x,z,heading,scale=.56){const a=Math.cos(heading)*scale,b=-Math.sin(heading)*scale,c=Math.sin(heading)*scale,d=Math.cos(heading)*scale;return [a,b,c,d,150-a*x-c*z,172-b*x-d*z];}
const wrap=a=>Math.atan2(Math.sin(a),Math.cos(a));
export function nextTurn(path,s,junctions=[]){if(path.length-s<35)return {icon:'✓',text:'Çamiçi · Varış',distance:'Güzergâh sonu'};const junction=junctions.find(j=>j.s>=s-8&&j.s-s<300);if(junction)return {icon:'↑',text:'Ayrımda ana yolda kal',distance:Math.max(0,Math.round((junction.s-s)/10)*10)+' m · '+(junction.side==='right'?'Sağda':'Solda')+' yan yol'};const p=path.sample(s),heading=Math.atan2(p.tx,-p.tz);for(let distance=30;distance<=400;distance+=15){const ahead=path.sample(s+distance),angle=wrap(Math.atan2(ahead.tx,-ahead.tz)-heading);if(Math.abs(angle)>.30)return {icon:angle>0?'↱':'↰',text:angle>0?'Sağa viraj':'Sola viraj',distance:distance+' m'};}return {icon:'↑',text:'Yolu takip et',distance:'Ünye–Niksar Yolu'};}
export class FollowNavigation{
 constructor(root,path,junctions=[]){this.root=root;this.path=path;this.last=-1e9;this.overview=false;this.scale=.56;this.group=root.querySelector('#navWorld');this.lines=[...root.querySelectorAll('.navRoute')];this.compass=root.querySelector('#navCompass');this.basemap=new NavigationBasemap(this.group,path);const ns='http://www.w3.org/2000/svg';
  const all=path.rows.map(p=>p[1]+','+p[3]).join(' ');this.lines[0].setAttribute('points',all);this.lines[1].setAttribute('points',all);
  for(const j of junctions){const branch=document.createElementNS(ns,'polyline');branch.setAttribute('points',j.points.map(p=>p.join(',')).join(' '));branch.setAttribute('fill','none');branch.setAttribute('stroke','#fff');branch.setAttribute('stroke-width','4');branch.setAttribute('stroke-linejoin','round');branch.setAttribute('vector-effect','non-scaling-stroke');this.group.insertBefore(branch,this.lines[0]);}
  const xs=path.rows.map(p=>p[1]),zs=path.rows.map(p=>p[3]);this.bounds={x:(Math.min(...xs)+Math.max(...xs))/2,z:(Math.min(...zs)+Math.max(...zs))/2,scale:Math.min(250/(Math.max(...xs)-Math.min(...xs)),190/(Math.max(...zs)-Math.min(...zs)))};
  this.marker=document.createElementNS(ns,'path');this.marker.setAttribute('d','M0 -13 L10 12 L0 7 L-10 12 Z');this.marker.setAttribute('fill','#1976ed');this.marker.setAttribute('stroke','white');this.marker.setAttribute('stroke-width','2');root.append(this.marker);
 }
 update(position,heading,station,speed=0,dt=1/60){if(this.heading===undefined)this.heading=heading;this.heading+=wrap(heading-this.heading)*(1-Math.exp(-9*dt));heading=this.heading;if(Math.abs(station-this.last)>3){const points=[],p=this.path.sample(station);points.push(p.x+','+p.z);for(let s=Math.ceil((station+.001)/4)*4;s<this.path.length;s+=4){const p=this.path.sample(s);points.push(p.x+','+p.z);}const end=this.path.sample(this.path.length);points.push(end.x+','+end.z);this.lines[2].setAttribute('points',points.join(' '));this.last=station;}
  for(let i=0;i<this.lines.length;i++)this.lines[i].setAttribute('stroke-width',(this.overview?[7,5,3]:[10,7,4])[i]);
  let matrix;if(this.overview){const b=this.bounds;matrix=[b.scale,0,0,b.scale,150-b.x*b.scale,120-b.z*b.scale];this.marker.setAttribute('transform',`translate(${position.x*b.scale+matrix[4]} ${position.z*b.scale+matrix[5]}) rotate(${heading*180/Math.PI})`);}else{const target=.62/(1+Math.abs(speed)/24);this.scale+=(target-this.scale)*(1-Math.exp(-3*dt));matrix=navigationTransform(position.x,position.z,heading,this.scale);this.marker.setAttribute('transform','translate(150 172)');}
  this.basemap.update(matrix,this.overview);
  this.group.setAttribute('transform','matrix('+matrix.map(v=>v.toFixed(6)).join(' ')+')');this.compass.setAttribute('transform','rotate('+(this.overview?0:-heading*180/Math.PI).toFixed(1)+' 274 26)');const label=this.root.querySelector('text');if(label)label.textContent=this.overview?'TÜM GÜZERGÂH · 11,41 km':Math.round(100/this.scale)+' m ━ · ARAÇ YÖNÜ YUKARI';
 }
}
